#include <Eigen/Dense>
#include <iostream>
#include <cmath>
#include <iomanip>

using namespace Eigen;
using namespace std;

// Global material properties (from MAT routine)
double G11, G12, G13, G22, G23, G33;

// GMMATD: general matrix multiply with optional transpose
// C = op(A) * op(B), where op = transpose if flag set
MatrixXd gmmatd(const MatrixXd& A, int transA, const MatrixXd& B, int transB) {
    MatrixXd At = transA ? A.transpose() : A;
    MatrixXd Bt = transB ? B.transpose() : B;
    return At * Bt;
}

// INVERD: matrix inversion (returns inverse, sets ising)
MatrixXd inverd(const MatrixXd& M, int& ising) {
    FullPivLU<MatrixXd> lu(M);
    if (!lu.isInvertible()) {
        ising = 2;
        return MatrixXd::Zero(M.rows(), M.cols());
    }
    ising = 1;
    return lu.inverse();
}

// KTRBSC - basic bending triangle
// Returns the 9 3x3 matrices (K^U) stored in A(1..81), plus Hinv (A(145..180)) and S (A(82..99))
// We'll implement IOPT=2 path which saves H-inverse and S.
struct KTRBSCResult {
    MatrixXd KU[3][3];   // KU[i][j] = 3x3 matrices, i,j = 0..2
    MatrixXd Hinv;       // 6x6
    MatrixXd S;          // 6x3
    double XSUBB, XSUBC, YSUBC;
    bool ok;
};

KTRBSCResult ktrbsc(double X1,double Y1,double Z1,
                    double X2,double Y2,double Z2,
                    double X3,double Y3,double Z3,
                    double EYE, double ANGLE, double T2,
                    double G11_,double G12_,double G13_,
                    double G22_,double G23_,double G33_) {
    KTRBSCResult res;
    res.ok = true;

    // E matrix 3x3 (columns: I, J, K vectors)
    Vector3d Ivec, Jvec, Kvec;

    // I-vector = RsubB - RsubA
    Vector3d d2(X2-X1, Y2-Y1, Z2-Z1);
    double XSUBB = d2.norm();
    if (XSUBB <= 1.0e-6) { res.ok=false; return res; }
    Ivec = d2 / XSUBB;

    // RsubC - RsubA
    Vector3d d1(X3-X1, Y3-Y1, Z3-Z1);
    double XSUBC = Ivec.dot(d1);

    // K-vector = I cross d1
    Kvec = Ivec.cross(d1);
    double YSUBC = Kvec.norm();
    if (YSUBC <= 1.0e-6) { res.ok=false; return res; }
    Kvec = Kvec / YSUBC;

    // J = K cross I
    Jvec = Kvec.cross(Ivec);
    Jvec.normalize();

    res.XSUBB = XSUBB;
    res.XSUBC = XSUBC;
    res.YSUBC = YSUBC;

    // G matrix (material)
    Matrix3d G;
    G << G11_, G12_, G13_,
         G12_, G22_, G23_,
         G13_, G23_, G33_;

    // D = I * G (EYE is moment of inertia)
    Matrix3d D = G * EYE;

    double AREA = XSUBB * YSUBC / 2.0;
    double XBAR = (XSUBB + XSUBC) / 3.0;
    double YBAR = YSUBC / 3.0;

    double XCSQ = XSUBC*XSUBC;
    double YCSQ = YSUBC*YSUBC;
    double XBSQ = XSUBB*XSUBB;
    double XCYC = XSUBC*YSUBC;
    double PX2 = (XBSQ + XSUBB*XSUBC + XCSQ)/6.0;
    double PY2 = YCSQ/6.0;
    double PXY2 = YSUBC*(XSUBB + 2.0*XSUBC)/12.0;
    double XBAR3 = 3.0*XBAR;
    double YBAR3 = 3.0*YBAR;
    double YBAR2 = 2.0*YBAR;

    // D indices: D(1)=D(0,0), D(2)=D(0,1), D(3)=D(0,2),
    //            D(4)=D(1,0), D(5)=D(1,1), D(6)=D(1,2),
    //            D(7)=D(2,0), D(8)=D(2,1), D(9)=D(2,2)
    // Fortran D is stored column-major: D(1)=D11, D(2)=D21, D(3)=D31,
    //   D(4)=D12, D(5)=D22, D(6)=D32, D(7)=D13, D(8)=D23, D(9)=D33
    // Wait - D is a 3x3 matrix stored in D(9). Fortran column-major.
    // D(1)=D(1,1), D(2)=D(2,1), D(3)=D(3,1), D(4)=D(1,2), D(5)=D(2,2), D(6)=D(3,2),
    // D(7)=D(1,3), D(8)=D(2,3), D(9)=D(3,3)
    // But D = G*EYE, and G is symmetric, so D is symmetric. So D(2)=D(4), D(3)=D(7), D(6)=D(8).
    // Let me use the Fortran indexing directly.
    double Dv[9];
    // D = G * EYE (scalar), so Dv = G elements * EYE in column-major
    // G stored column-major: G(1)=G11, G(2)=G21, G(3)=G31, G(4)=G12, G(5)=G22, G(6)=G32, G(7)=G13, G(8)=G23, G(9)=G33
    Dv[0] = G11_*EYE; Dv[1] = G12_*EYE; Dv[2] = G13_*EYE;
    Dv[3] = G12_*EYE; Dv[4] = G22_*EYE; Dv[5] = G23_*EYE;
