    setA(2,3, getA(3,2));
    setA(3,3, Dv[4]);
    setA(4,3, Dv[1]*XBAR3);
    setA(5,3, Dv[4]*XBAR + YBAR2*Dv[5]);
    setA(6,3, Dv[4]*YBAR3);
    setA(1,4, getA(4,1));
    setA(2,4, getA(4,2));
    setA(3,4, getA(4,3));
    setA(4,4, Dv[0]*9.0*PX2);
    setA(5,4, Dv[1]*3.0*PX2 + 6.0*PXY2*Dv[2]);
    setA(6,4, Dv[1]*9.0*PXY2);
    setA(1,5, getA(5,1));
    setA(2,5, getA(5,2));
